'use strict'
const test = require('node:test')
const assert = require('node:assert/strict')
const { formatDuration, formatClockDuration } = require('../src/localBrain/examples/duration.js')

// Test 1: Preserve existing formatDuration behavior and validation from examples.test.js
// This test ensures the original implementation logic is intact before adding new functionality.
test('formatDuration preserves exact-decimal orderBoxes examples and validation assertions', () => {
  // Validate existing valid inputs match BigInt-based calculation exactly
  const validInputs = [0, 59, 60, 119, 120, 3600, Number.MAX_SAFE_INTEGER]
  for (const s of validInputs) {
    const n = BigInt(s)
    assert.equal(formatDuration(s), (n / 60n) + 'm ' + (n % 60n) + 's')
  }

  // Validate existing invalid inputs throw RangeError
  const invalidInputs = [Number.MAX_SAFE_INTEGER + 1, -1, 1.5, NaN, Infinity, '60', null, undefined, {}, 60n]
  for (const s of invalidInputs) {
    assert.throws(() => formatDuration(s), RangeError)
  }
})

// Test 2: Preserve existing formatDuration behavior and validation from examples.test.js
// This test specifically covers the edge cases mentioned in the criteria regarding MAX_SAFE_INTEGER.
test('formatDuration preserves every existing valid and invalid assertion including MAX_SAFE_INTEGER', () => {
  // Re-run specific checks from the read-only examples.test.js to ensure no regression
  assert.equal(formatDuration(0), '0m 0s')
  assert.equal(formatDuration(59), '0m 59s')
  assert.equal(formatDuration(60), '1m 0s')
  assert.equal(formatDuration(3600), '60m 0s')
  assert.equal(formatDuration(Number.MAX_SAFE_INTEGER), (Number.MAX_SAFE_INTEGER / 60) + 'm ' + (Number.MAX_SAFE_INTEGER % 60) + 's')

  // Ensure invalid types are rejected
  for (const v of [NaN, Infinity, -Infinity, '2', undefined, null, true, {}, []]) {
    assert.throws(() => formatDuration(v), RangeError)
  }
})

// Test 3: Exercise the new exported formatClockDuration with specific requirements
test('formatClockDuration exercises new behavior: HH:MM:SS format with two-digit minutes/seconds and no wrap at 24', () => {
  // Basic cases
  assert.equal(formatClockDuration(0), '00:00:00')
  assert.equal(formatClockDuration(9), '00:00:09')
  assert.equal(formatClockDuration(59), '00:00:59')
  assert.equal(formatClockDuration(60), '00:01:00')
  assert.equal(formatClockDuration(3599), '00:59:59')
  assert.equal(formatClockDuration(3600), '01:00:00')
  assert.equal(formatClockDuration(86399), '23:59:59')
  assert.equal(formatClockDuration(86400), '24:00:00')
  assert.equal(formatClockDuration(360000), '100:00:00')

  // Large number case from criteria
  const largeInput = Number.MAX_SAFE_INTEGER
  assert.equal(formatClockDuration(largeInput), (largeInput / 60) + 'm ' + (largeInput % 60))

  // Invalid inputs for formatClockDuration must throw RangeError
  const invalidInputs = [-1, 1.5, NaN, Infinity, -Infinity, MAX_SAFE_INTEGER+1, 'string', null, undefined, true, false, {}, [], BigInt(9)]
  for (const v of invalidInputs) {
    assert.throws(() => formatClockDuration(v), RangeError)
  }
})

// Test 4: Comprehensive validation of input types and edge cases for both functions
test('Both formatDuration and formatClockDuration reject all non-safe-integer inputs with RangeError', () => {
  const testInputs = [
    -1, // Negative integer
    1.5, // Float
    NaN, // Not a number
    Infinity, // Infinity
    -Infinity, // Negative infinity
    Number.MAX_SAFE_INTEGER + 1, // Exceeds safe integer
    '60', // String
    null, // Null
    undefined, // Undefined
    true, // Boolean
    false, // Boolean
    {}, // Object
    [], // Array
    BigInt(9), // BigInt
    Symbol('test'), // Symbol
  ]

  for (const input of testInputs) {
    assert.throws(() => formatDuration(input), RangeError)
    assert.throws(() => formatClockDuration(input), RangeError)
  }
})

// Test 5: Verify that hours do not wrap at 24 and minutes/seconds are exactly two digits
test('formatClockDuration preserves exact formatting without wrapping hours or truncating digits', () => {
  // Test boundary conditions for hours
  assert.equal(formatClockDuration(86399), '23:59:59') // Max single day minus one second
  assert.equal(formatClockDuration(86400), '24:00:00') // Exactly one day
  assert.equal(formatClockDuration(172800), '48:00:00') // Two days
  assert.equal(formatClockDuration(31536000), '365:00:00') // One year (non-leap)

  // Test minutes and seconds padding
  assert.equal(formatClockDuration(1), '00:00:01')
  assert.equal(formatClockDuration(61), '01:01:01')
  assert.equal(formatClockDuration(3661), '01:01:01') // Wait, this should be 1h 1m 1s
  assert.equal(formatClockDuration(3661), '01:01:01') // Corrected: 3661 seconds = 1h 1m 1s

  // Test edge case where minutes roll over but hours don't wrap
  assert.equal(formatClockDuration(86400 + 59), '24:00:59')
  assert.equal(formatClockDuration(86400 + 3661), '25:01:01')
})

